fn frame(t: i32) {
    host::display::clear(0x10141a);
    if host::display::state_get(0) == 0 {
        host::mp::auto(5);
        host::display::state_set(0, 1);
    }
    let me: i32 = host::mp::self_index();
    if me < 0 {
        host::display::draw_string(140, 220, "JOINING ROOM", 0x8899aa, 2);
        let dots: i32 = (t / 15) % 4;
        let mut d: i32 = 0;
        while d < dots {
            host::display::fill_rect(220 + d * 20, 270, 10, 10, 0xffcc33);
            d = d + 1;
        }
    } else {
        host::mp::set(0, host::display::pointer_x());
        host::mp::set(1, host::display::pointer_y());
        let n: i32 = host::mp::peer_count();
        let mut i: i32 = 0;
        while i < n {
            let cx: i32 = host::mp::get(i, 0);
            let cy: i32 = host::mp::get(i, 1);
            let mut col: i32 = 0x33ff88;
            if i == me {
                col = 0xffcc33;
            }
            host::display::fill_rect(cx - 7, cy - 7, 14, 14, col);
            host::display::draw_number(cx - 3, cy - 22, i, 0xffffff, 1);
            i = i + 1;
        }
        host::display::draw_string(8, 8, "SHARED CURSORS", 0x8899aa, 1);
        host::display::draw_string(8, 490, "PEERS", 0x8899aa, 1);
        host::display::draw_number(56, 488, n, 0xffffff, 1);
    }
    host::display::present();
}
